INSERT INTO mosques (id, slug, name, subtitle, type, street, zip, city, district, lat, lng, opened_year, image, image_alt, short_description, description, features, email, booking_email, phone, sort_order) VALUES
  (1, 'nahe', 'Bait-ul-Baseer Moschee', 'Zentrum Mahdiabad · Nahe', 'mosque', 'Wakendorfer Straße 11', '23866', 'Nahe', 'Kreis Segeberg', 53.8027, 10.1404, 2019, '/assets/img/mosques/nahe.jpg', 'Die Bait-ul-Baseer Moschee in Nahe', 'Das Zentrum Mahdiabad mit der Bait-ul-Baseer Moschee ist ein Ort des Gebets, der Begegnung und der Gemeinschaft im Kreis Segeberg.', 'Die Bait-ul-Baseer Moschee liegt auf dem Gelände Mahdiabad in Nahe. Sie wurde am 25. Oktober 2019 vom Oberhaupt der weltweiten Ahmadiyya Muslim Jamaat, Hadhrat Mirza Masroor Ahmad (aba), eröffnet. Das Gelände bietet Raum für Gebete, Veranstaltungen, Jugendarbeit und den Austausch mit Nachbarn. Besucherinnen und Besucher sind herzlich willkommen – wir zeigen Ihnen gern die Moschee und beantworten Ihre Fragen zum Islam.', '["Gebetsräume für Männer und Frauen","Veranstaltungsgelände","Parkplätze vorhanden"]', 'mashhood.zafar@ahmadiyya.de', NULL, NULL, 1),
  (2, 'luebeck', 'Bait-ul-Afiyat Moschee', 'Lübeck', 'mosque', 'Kaninchenborn 4a', '23560', 'Lübeck', 'Hansestadt Lübeck', 53.8483, 10.6526, 2011, '/assets/img/mosques/luebeck.jpg', 'Die Bait-ul-Afiyat Moschee in Lübeck', 'Die Bait-ul-Afiyat Moschee – „Haus des Wohlergehens“ – ist seit 2011 ein offenes Haus in der Hansestadt Lübeck.', 'Die Bait-ul-Afiyat Moschee („Haus des Wohlergehens“) wurde im Juni 2011 eingeweiht. Seitdem ist sie Treffpunkt der Gemeinde in Lübeck und ein offenes Haus für alle, die den Islam und die Ahmadiyya Muslim Jamaat kennenlernen möchten. Regelmäßig finden hier Tage der offenen Tür, interreligiöse Begegnungen und Führungen für Schulklassen statt.', '["Gebetsräume für Männer und Frauen","Führungen für Schulklassen"]', 'luebeck@ahmadiyya.email', NULL, NULL, 2),
  (3, 'kiel', 'Habib Moschee', 'Kiel', 'mosque', 'Flintbeker Straße 7', '24113', 'Kiel', 'Landeshauptstadt Kiel', 54.2905, 10.1157, NULL, '/assets/img/mosques/kiel.jpg', 'Die Habib Moschee in Kiel', 'Die Habib Moschee in der Landeshauptstadt ist Gebetsort und Begegnungsstätte – mit vielen Besuchen von Schulen, Universität und Politik.', 'Die Habib Moschee in Kiel ist das Zuhause der Gemeinde in der Landeshauptstadt. Hier begrüßen wir regelmäßig Schulklassen, Studierende der Universität Kiel, Vertreterinnen und Vertreter aus Politik und Gesellschaft sowie Nachbarn. Neben Gebeten und Vorträgen engagiert sich die Gemeinde bei Neujahrsputzaktionen, Baumpflanzungen und Blutspendeaktionen.', '["Gebetsräume für Männer und Frauen","Vorträge & Gesprächsabende","Führungen für Gruppen"]', 'kiel@ahmadiyya.de', NULL, NULL, 3),
  (4, 'husum', 'Mahmood Moschee', 'Husum', 'mosque', 'Robert-Koch-Straße 33', '25813', 'Husum', 'Kreis Nordfriesland', 54.4766, 9.0612, NULL, '/assets/img/mosques/placeholder.svg', 'Platzhalterbild der Mahmood Moschee in Husum', 'Die Mahmood Moschee in Husum ist der Treffpunkt der Gemeinde an der Nordseeküste in Nordfriesland.', 'Die Mahmood Moschee in Husum ist Gebetsort und Begegnungsstätte der Ahmadiyya Muslim Jamaat in Nordfriesland. Beim jährlichen Tag der offenen Moschee am 3. Oktober und auf Anfrage öffnen wir unsere Türen für alle Interessierten.', '["Gebetsraum","Tag der offenen Moschee"]', NULL, NULL, NULL, 4),
  (5, 'pinneberg', 'Gemeindezentrum Pinneberg', 'Pinneberg', 'center', 'Adresse folgt', NULL, 'Pinneberg', 'Kreis Pinneberg', 53.6603, 9.7964, NULL, '/assets/img/mosques/placeholder.svg', 'Platzhalterbild des Gemeindezentrums Pinneberg', 'Das Gemeindezentrum in Pinneberg ist Anlaufstelle für Gebet und Gemeinschaft im Hamburger Umland.', 'Im Gemeindezentrum Pinneberg kommt die örtliche Gemeinde der Ahmadiyya Muslim Jamaat zu Gebeten, Versammlungen und Veranstaltungen zusammen. Gern vereinbaren wir mit Ihnen einen Besuchstermin.', '["Gebetsraum","Gemeinschaftsräume"]', NULL, NULL, NULL, 5);
