INSERT INTO events (id, mosque_id, title, description, starts_at, ends_at, location, image) VALUES
  (1, NULL, 'Neujahrsputzaktion 2027', 'Wie jedes Jahr am Neujahrsmorgen räumen junge Ahmadi-Muslime in vielen Städten Schleswig-Holsteins die Straßen auf. Helfende Hände sind willkommen!', '2027-01-01T08:00:00.000Z', '2027-01-01T11:00:00.000Z', 'Kiel, Lübeck, Husum, Nahe, Pinneberg', NULL),
  (2, 3, 'Interreligiöser Gesprächsabend', 'Vertreter verschiedener Religionen sprechen über Frieden und gesellschaftlichen Zusammenhalt. Mit anschließendem Tee und Gebäck.', '2026-12-03T17:30:00.000Z', '2026-12-03T20:00:00.000Z', 'Habib Moschee, Kiel', NULL),
  (3, 2, 'Tag der offenen Tür', 'Lernen Sie die Bait-ul-Afiyat Moschee kennen: Führungen, Ausstellung über den Islam, Fragen & Antworten.', '2027-02-14T13:00:00.000Z', '2027-02-14T17:00:00.000Z', 'Bait-ul-Afiyat Moschee, Lübeck', NULL);
INSERT INTO highlights (id, mosque_id, title, summary, date, image, link) VALUES
  (1, 4, 'Tag der offenen Moschee in Husum', 'Am 3. Oktober 2026 besuchten zahlreiche Gäste die Mahmood Moschee und informierten sich über den Islam.', '2026-10-03', NULL, NULL),
  (2, 3, 'Tag der offenen Moschee in Kiel', 'Führungen, eine Ausstellung und viele Gespräche bei Tee – ein Tag der Begegnung in der Habib Moschee.', '2026-10-03', NULL, NULL),
  (3, NULL, 'Baumpflanzaktionen im ganzen Land', 'Die Jugendorganisation pflanzte gemeinsam mit Kommunen hunderte Bäume – Umweltschutz als gelebter Glaube.', '2026-04-18', NULL, NULL);
INSERT INTO feedback (id, mosque_id, name, visit_type, rating, text, visited_on, status, created_at) VALUES
  (1, 3, 'Klasse 10b, Gymnasium', 'school', 5, 'Sehr herzlicher Empfang! Der Imam hat alle unsere Fragen geduldig beantwortet. Für viele war es der erste Besuch in einer Moschee.', '2026-09-12', 'approved', '2026-09-14T10:00:00Z'),
  (2, 2, 'Sabine M.', 'individual', 5, 'Ich war neugierig und etwas unsicher – aber ich wurde so freundlich aufgenommen. Ein offenes Gespräch über Glauben und Alltag, vielen Dank!', '2026-08-20', 'approved', '2026-08-21T18:00:00Z'),
  (3, 1, 'Seniorenkreis der Kirchengemeinde', 'group', 5, 'Eine beeindruckende Moschee und eine wunderbare Gastfreundschaft. Besonders der Austausch über Gemeinsamkeiten unserer Religionen hat uns berührt.', '2026-06-05', 'approved', '2026-06-07T09:30:00Z'),
  (4, 4, 'Familie J.', 'individual', 4, 'Schöner Tag der offenen Moschee. Die Kinder haben ihren Namen auf Arabisch geschrieben bekommen – ein tolles Erlebnis.', '2026-10-03', 'approved', '2026-10-04T12:00:00Z');
